1	#include "Led.hpp"
2	
3	#include "stm.hpp"
4	#include "FreeRTOS.h"
5	#include "task.h"
6	
7	#if HW_REVISION == 'B'
8	
9	#define LED_STATUS_TASK_STACK_SIZE_WORDS	128
10	
11	extern TIM_HandleTypeDef htim2;
12	
13	enum class Mode {
14		Off,
15		On,
16		Blink,
17		Pulsating,
18		Error,
19	};
20	
21	static Mode mode;
22	static uint8_t led_statecnt;
23	static int8_t led_ncnt;
24	
25	static StackType_t LedStatusStack[LED_STATUS_TASK_STACK_SIZE_WORDS];
26	static StaticTask_t LedStatusCB;
27	static xTaskHandle LedStatusHandle = NULL;
28	
29	static uint8_t err_cnt;
30	
31	static void led_set_percentage(uint8_t val) {
32		uint16_t compare = val * val / 100;
33		TIM2->CCR1 = compare;
34	}
35	
36	static void LedStatus(void * const argument) {
37		UNUSED(argument);
38		while (1) {
39			if (led_statecnt < 199) {
40				led_statecnt++;
41			} else {
42				led_statecnt = 0;
43			}
44			switch (mode) {
45			case Mode::Off:
46				led_set_percentage(0);
47				vTaskSuspend(NULL);
48				break;
49			case Mode::On:
50				led_set_percentage(100);
51				vTaskSuspend(NULL);
52				break;
53			case Mode::Error:
54				if (led_statecnt == 0) {
55					err_cnt++;
56					if (err_cnt > led_ncnt) {
57						// reached number of blinks + 1
58						err_cnt = 0;
59					}
60				}
61				if (err_cnt >= led_ncnt) {
62					break;
63				}
64				// fall through
65				/* no break */
66			case Mode::Blink:
67				if(led_statecnt < 100) {
68					led_set_percentage(100);
69				} else {
70					led_set_percentage(0);
71				}
72				break;
73			case Mode::Pulsating:
74				if (led_statecnt < 100) {
75					led_set_percentage(led_statecnt);
76				} else {
77					led_set_percentage(200 - led_statecnt);
78				}
79				break;
80			}
81			vTaskDelay(5);
82		}
83	}
84	#endif
85	
86	void LED::Init() {
87	#if HW_REVISION == 'B'
88		led_ncnt = 0;
89		mode = Mode::Off;
90		HAL_TIM_Base_Start(&htim2);
91		HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_1);
92	
93		LedStatusHandle = xTaskCreateStatic(LedStatus, "LedStatusTask", LED_STATUS_TASK_STACK_SIZE_WORDS,
94											NULL, 6, LedStatusStack, &LedStatusCB);
95	
96		vTaskSuspend(LedStatusHandle);
97	#endif
98	}
99	
100	void LED::Pulsating() {
101	#if HW_REVISION == 'B'
102		if(led_ncnt) {
103			return;
104		}
105		vTaskSuspend(LedStatusHandle);
106		mode = Mode::Pulsating;
107		vTaskResume(LedStatusHandle);
108	#endif
109	}
110	
111	void LED::Off() {
112	#if HW_REVISION == 'B'
113		if(led_ncnt) {
114			return;
115		}
116		vTaskSuspend(LedStatusHandle);
117		mode = Mode::Off;
118		vTaskResume(LedStatusHandle);
119	#endif
120	}
121	
122	void LED::Error(uint8_t code) {
123	#if HW_REVISION == 'B'
124		if(led_ncnt) {
125			return;
126		}
127		vTaskSuspend(LedStatusHandle);
128		mode = Mode::Error;
129		led_statecnt = 0;
